1	package vault
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14	)
15	
16	// Snapshot is an immutable record of every name mapping in the repository at
17	// creation time. It only references existing content objects; no artifact
18	// bytes are copied.
19	type Snapshot struct {
20		Name    string           `json:"name"`
21		Entries map[string]Entry `json:"entries"`
22	}
23	
24	// SnapshotInfo summarizes a saved snapshot for listing.
25	type SnapshotInfo struct {
26		Name  string
27		Count int
28	}
29	
30	// CreateSnapshot records the current name mapping under the given snapshot
31	// name. It first requires the current mapping itself to be complete and
32	// unambiguous — the index is loaded with the same strict rules verify and gc
33	// apply (a bare null, an empty {}, a missing or null entries mapping, a
34	// non-object entries value, a truncated document, trailing content, or any
35	// duplicate key at any level — including a name repeated through Unicode
36	// escapes — is corruption, while a genuine {"entries":{}} is a legitimate
37	// empty repository), and every record is keyed by its recorded name and
38	// carries a legal name, a 64-character lowercase-hex digest, and a
39	// non-negative size. Validation runs before anything is written and is
40	// all-or-nothing: one bad record rejects the whole operation; bad entries are
41	// never skipped to leave a seemingly usable partial snapshot.
42	//
43	// Index problems are reported as "cannot create snapshot <name>: current
44	// index is corrupt: <reason>", with the duplicated key or offending artifact
45	// named, distinct from an illegal snapshot name and from an existing snapshot
46	// (snapshot %q already exists). On failure no snapshot record is created —
47	// saveSnapshot itself writes a temporary file and renames it into place — and
48	// the index's original bytes, existing snapshots, and content objects are
49	// untouched. The snapshot records metadata only and references existing
50	// objects; content is re-verified by restore and export under their existing
51	// rules.
52	func (s *Store) CreateSnapshot(name string) (Snapshot, error) {
53		if err := validateName(name); err != nil {
54			return Snapshot{}, err
55		}
56		var snap Snapshot
57		err := s.withLock(true, func() error {
58			if err := s.initLocked(); err != nil {
59				return err
60			}
61			idx, err := s.loadStrict()
62			if err != nil {
63				return fmt.Errorf("cannot create snapshot %q: %w", name, err)
64			}
65			// Validate every record before writing anything, in sorted order so the
66			// first reported bad entry is deterministic. One bad record rejects the
67			// whole snapshot; the mapping is never filtered into a partial backup.
68			keys := make([]string, 0, len(idx.Entries))
69			for key := range idx.Entries {
70				keys = append(keys, key)
71			}
72			sort.Strings(keys)
73			for _, key := range keys {
74				if err := validateEntryRecord(key, idx.Entries[key]); err != nil {
75					return fmt.Errorf("cannot create snapshot %q: current index is corrupt: %w", name, err)
76				}
77			}
78			path := s.snapshotPath(name)
79			if _, err := os.Stat(path); err == nil {
80				return fmt.Errorf("snapshot %q already exists", name)
81			} else if !errors.Is(err, os.ErrNotExist) {
82				return err
83			}
84			snap = Snapshot{Name: name, Entries: idx.Entries}
85			return s.saveSnapshot(path, snap)
86		})
87		if err != nil {
88			return Snapshot{}, err
89		}
90		return snap, nil
91	}
92	
93	// ListSnapshots returns every saved snapshot, sorted by its complete snapshot
94	// name, with the number of artifact records in its entries mapping.
95	//
96	// A snapshot is listed only after its record proves complete and legal: it is
97	// validated exactly the way RestoreSnapshot validates the record it restores
98	// (see decodeSnapshotRecord) — a single JSON object whose recorded name
99	// equals its filing name in full ("releases/stable", never just "stable"),
100	// with a present, object-valued entries mapping ({} is a legitimate empty
101	// snapshot; a missing or null entries field is corruption) containing only
102	// valid artifact records. The content objects the entries reference are not
103	// read or checked; listing depends on neither the objects nor the health of
104	// the current name mapping.
105	//
106	// One damaged, unreadable, or misplaced record fails the whole operation:
107	// the error names the complete snapshot and what is wrong with it and no
108	// SnapshotInfo is returned, so callers never see a partial list or read a
109	// name or count off a corrupt record. A repository whose snapshots directory
110	// does not exist yet simply has no snapshots and yields an empty list; a
111	// record read failing with "not exist" once the directory walk has started
112	// is reported rather than treated as absence. Non-snapshot files (temporary
113	// files and anything not ending in .json) are ignored. Listing never
114	// modifies the current mapping, any snapshot record, or any content object.
115	func (s *Store) ListSnapshots() ([]SnapshotInfo, error) {
116		infos := []SnapshotInfo{}
117		err := s.withLock(false, func() error {
118			return s.walkSnapshotRecords(func(name string, snap Snapshot) error {
119				infos = append(infos, SnapshotInfo{Name: name, Count: len(snap.Entries)})
120				return nil
121			})
122		})
123		if err != nil {
124			return nil, err
125		}
126		sort.Slice(infos, func(i, j int) bool { return infos[i].Name < infos[j].Name })
127		return infos, nil
128	}
129	
130	// walkSnapshotRecords enumerates the snapshot records filed under snapshots/
131	// and invokes fn with each record's complete snapshot name and its parsed,
132	// fully validated contents (see decodeSnapshotRecord). It is the single
133	// enumeration used by read-only operations that must see exactly the records
134	// restore would accept — listing and reference collection alike.
135	//
136	// A missing snapshots directory means no snapshots exist and is not an error.
137	// Every other problem aborts the walk: a symlinked or non-directory snapshots
138	// path, a symlink or other non-regular file beneath it, a .json file whose
139	// location does not encode a legal snapshot name, a record that cannot be
140	// read (including one that disappears mid-walk), and any malformed or
141	// incomplete record. Errors name the complete snapshot when its location is
142	// known. Files without a .json suffix (temporary files and other stray data)
143	// are skipped.
144	func (s *Store) walkSnapshotRecords(fn func(name string, snap Snapshot) error) error {
145		dir := s.snapshotsDir()
146		info, err := os.Lstat(dir)
147		switch {
148		case errors.Is(err, os.ErrNotExist):
149			return nil
150		case err != nil:
151			return fmt.Errorf("cannot inspect snapshots directory: %w", err)
152		case info.Mode()&os.ModeSymlink != 0:
153			return fmt.Errorf("snapshots path %q is a symbolic link", dir)
154		case !info.IsDir():
155			return fmt.Errorf("snapshots path %q is not a directory", dir)
156		}
157		return filepath.WalkDir(dir, func(path string, d fs.DirEntry, walkErr error) error {
158			if walkErr != nil {
159				// The directory entry was seen but the path can no longer be
160				// accessed: a vanished record is a read failure, not an empty set.
161				return walkErr
162			}
163			if d.IsDir() {
164				return nil
165			}
166			rel, err := filepath.Rel(dir, path)
167			if err != nil {
168				return err
169			}
170			isRecord := strings.HasSuffix(d.Name(), ".json")
171			// Name the snapshot when the offending path occupies a record slot;
172			// other stray entries are identified by path.
173			if d.Type()&os.ModeSymlink != 0 {
174				if isRecord {
175					name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
176					return fmt.Errorf("snapshot %q is a symbolic link", name)
177				}
178				return fmt.Errorf("snapshots contain symbolic link %q", path)
179			}
180			if !d.Type().IsRegular() {
181				if isRecord {
182					name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
183					return fmt.Errorf("snapshot %q is not a regular file", name)
184				}
185				return fmt.Errorf("snapshots contain non-regular file %q", path)
186			}
187			if !isRecord {
188				return nil
189			}
190			name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
191			if err := validateName(name); err != nil {
192				return fmt.Errorf("snapshot record %q does not map to a valid snapshot name: %w", path, err)
193			}
194			data, err := os.ReadFile(path)
195			if err != nil {
196				return fmt.Errorf("snapshot %q cannot be read: %w", name, err)
197			}
198			snap, err := decodeSnapshotRecord(data, name)
199			if err != nil {
200				return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
201			}
202			return fn(name, snap)
203		})
204	}
205	
206	// RestoreSnapshot replaces the current name mapping with the snapshot's
207	// recorded mapping in a single atomic index write. The current index is never
208	// read, so restore works even when it is corrupted. The selected snapshot
209	// record must be a complete, well-formed document whose recorded name equals
210	// the selected snapshot name in full (a record nested under "releases/stable"
211	// must itself say "releases/stable", never just "stable") and whose entries
212	// mapping is present and an object ({} is a legitimate empty snapshot; a
213	// missing, null, or non-object entries field is corruption, never an empty
214	// mapping). Every referenced object is checked for existence, size, and
215	// SHA-256 before the mapping is swapped; any failure leaves the current
216	// mapping's bytes and all snapshots and objects untouched, even when the
217	// current mapping itself is already corrupted.
218	func (s *Store) RestoreSnapshot(name string) error {
219		if err := validateName(name); err != nil {
220			return err
221		}
222		return s.withLock(true, func() error {
223			if err := s.initLocked(); err != nil {
224				return err
225			}
226			snap, err := s.loadSnapshotRecord(name)
227			if err != nil {
228				return err
229			}
230			for _, entry := range snap.Entries {
231				if err := s.verifyObject(entry); err != nil {
232					return fmt.Errorf("cannot restore snapshot %q: object for %q: %w", name, entry.Name, err)
233				}
234			}
235			return s.save(index{Entries: snap.Entries})
236		})
237	}
238	
239	// decodeSnapshotRecord parses one snapshot record without touching the
240	// repository. wantName is the full snapshot name the record is selected or
241	// filed under and must record verbatim.
242	//
243	// A valid record is exactly one JSON object — never the bare null — with no
244	// duplicate or unknown fields and no trailing data, carrying:
245	//
246	//   - "name": present and a string equal to wantName, including every level of
247	//     a multi-level name; a missing, wrong-type, or merely-suffixed name
248	//     (record "stable" under "releases/stable") is refused;
249	//   - "entries": present and a JSON object. {} is a legitimate empty mapping;
250	//     a missing field, a null, an array, or any non-object value is
251	//     corruption rather than zero entries.
252	//
253	// Every entry is then checked with validateEntryRecord. The errors
254	// distinguish a missing entries mapping, a mismatching recorded name, and a
255	// malformed document so callers can tell record corruption apart from a
256	// snapshot that simply does not exist (that distinction is made by the
257	// caller, which checks the file before reading it).
258	func decodeSnapshotRecord(data []byte, wantName string) (Snapshot, error) {
259		if err := rejectDuplicateKeys(data); err != nil {
260			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
261		}
262		// The document must be a JSON object: a bare null, array, or primitive is
263		// a malformed record, never an empty snapshot.
264		if trimmed := bytes.TrimSpace(data); len(trimmed) == 0 || trimmed[0] != '{' {
265			return Snapshot{}, errors.New("malformed record: expected a JSON object with name and entries")
266		}
267		var raw struct {
268			Name    *string          `json:"name"`
269			Entries *json.RawMessage `json:"entries"`
270		}
271		dec := json.NewDecoder(bytes.NewReader(data))
272		dec.DisallowUnknownFields()
273		if err := dec.Decode(&raw); err != nil {
274			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
275		}
276		if tok, err := dec.Token(); err != io.EOF {
277			if err == nil {
278				return Snapshot{}, fmt.Errorf("malformed record: unexpected trailing content after the snapshot object (%v)", tok)
279			}
280			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
281		}
282		if raw.Name == nil {
283			return Snapshot{}, errors.New("malformed record: missing snapshot name")
284		}
285		if *raw.Name != wantName {
286			return Snapshot{}, fmt.Errorf("recorded name %q does not match snapshot %q", *raw.Name, wantName)
287		}
288		if raw.Entries == nil {
289			return Snapshot{}, errors.New("record is missing its entries mapping")
290		}
291		entriesJSON := *raw.Entries
292		if string(bytes.TrimSpace(entriesJSON)) == "null" {
293			return Snapshot{}, errors.New("record is missing its entries mapping")
294		}
295		var entries map[string]Entry
296		if err := json.Unmarshal(entriesJSON, &entries); err != nil {
297			return Snapshot{}, fmt.Errorf("entries mapping is malformed: %w", err)
298		}
299		if entries == nil {
300			return Snapshot{}, errors.New("record is missing its entries mapping")
301		}
302		for key, entry := range entries {
303			if err := validateEntryRecord(key, entry); err != nil {
304				return Snapshot{}, err
305			}
306		}
307		return Snapshot{Name: *raw.Name, Entries: entries}, nil
308	}
309	
310	func (s *Store) saveSnapshot(path string, snap Snapshot) error {
311		data, err := json.MarshalIndent(snap, "", "  ")
312		if err != nil {
313			return err
314		}
315		data = append(data, '\n')
316		if err := s.ensureSnapshotParent(path); err != nil {
317			return err
318		}
319		dir := filepath.Dir(path)
320		tmp, err := os.CreateTemp(dir, ".snapshot-*")
321		if err != nil {
322			return err
323		}
324		tmpName := tmp.Name()
325		defer os.Remove(tmpName)
326		if _, err := tmp.Write(data); err != nil {
327			tmp.Close()
328			return err
329		}
330		if err := tmp.Close(); err != nil {
331			return err
332		}
333		return os.Rename(tmpName, path)
334	}
335	
336	// ensureSnapshotParent creates the parent directories of a snapshot record one
337	// component at a time, refusing to follow symbolic links. Without this a nested
338	// snapshot name such as "evil/x" could be redirected through a pre-created
339	// snapshots/evil symlink to write outside the repository.
340	func (s *Store) ensureSnapshotParent(path string) error {
341		base := s.snapshotsDir()
342		rel, err := filepath.Rel(base, filepath.Dir(path))
343		if err != nil {
344			return err
345		}
346		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
347			return errors.New("snapshot path escapes the snapshots directory")
348		}
349		// The base directory itself must exist and be a real directory, even for a
350		// top-level snapshot (a freshly initialized repository has no snapshots/).
351		cur := base
352		if err := ensureRealDir(cur); err != nil {
353			return err
354		}
355		if rel == "." {
356			return nil
357		}
358		for _, component := range strings.Split(rel, string(filepath.Separator)) {
359			next := filepath.Join(cur, component)
360			if err := ensureRealDir(next); err != nil {
361				return err
362			}
363			cur = next
364		}
365		return nil
366	}
367	
368	// ensureRealDir makes sure path is a real directory, creating it if absent,
369	// and refuses an existing symlink or non-directory.
370	func ensureRealDir(path string) error {
371		info, err := os.Lstat(path)
372		switch {
373		case errors.Is(err, os.ErrNotExist):
374			if err := os.Mkdir(path, 0o755); err != nil && !errors.Is(err, os.ErrExist) {
375				return err
376			}
377			info, err = os.Lstat(path)
378			if err != nil {
379				return err
380			}
381		case err != nil:
382			return err
383		}
384		if info.Mode()&os.ModeSymlink != 0 {
385			return fmt.Errorf("repository path %q is a symbolic link", path)
386		}
387		if !info.IsDir() {
388			return fmt.Errorf("repository path %q is not a directory", path)
389		}
390		return nil
391	}
392	
393	func (s *Store) snapshotsDir() string { return filepath.Join(s.root, "snapshots") }
394	
395	func (s *Store) snapshotPath(name string) string {
396		return filepath.Join(s.snapshotsDir(), filepath.FromSlash(name)+".json")
397	}
398	
399	func isDigest(digest string) bool {
400		if len(digest) != 64 {
401			return false
402		}
403		for _, c := range digest {
404			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
405				return false
406			}
407		}
408		return true
409	}
