92				continue
93			}
94			if _, ok := referenced[dirent.Name()]; ok {
95				continue
96			}
97			fi, err := dirent.Info()
98			if err != nil {
99				return GCReport{}, fmt.Errorf("cannot stat object %q: %w", dirent.Name(), err)
100			}
101			candidates = append(candidates, GCCandidate{Digest: dirent.Name(), Size: fi.Size()})
102		}
103		sort.Slice(candidates, func(i, j int) bool { return candidates[i].Digest < candidates[j].Digest })
104		report := GCReport{Candidates: candidates}
105		if dryRun {
106			return report, nil
107		}
108		for _, candidate := range candidates {
109			if err := os.Remove(s.objectPath(candidate.Digest)); err != nil {
110				return report, fmt.Errorf("deleted %d objects (%d bytes), then failed to delete object %s: %w",
111					report.Deleted, report.Bytes, candidate.Digest, err)
112			}
113			report.Deleted++
114			report.Bytes += candidate.Size
115		}
116		return report, nil
117	}
118	
119	// collectReferences gathers every digest referenced by the current index and
120	// by all saved snapshots. Any record that cannot be read or fails validation
121	// is an error: GC must never guess whether a reference exists.
122	func (s *Store) collectReferences() (map[string]struct{}, error) {
123		referenced := map[string]struct{}{}
124		idx, err := s.loadStrict()
125		if err != nil {
126			return nil, fmt.Errorf("cannot collect references: current index is unusable: %w", err)
127		}
128		for key, entry := range idx.Entries {
129			if err := validateEntryRecord(key, entry); err != nil {
130				return nil, fmt.Errorf("current index is invalid: %w", err)
131			}
132			referenced[entry.Digest] = struct{}{}
133		}
134		// Every snapshot record is enumerated and validated exactly as list and
135		// restore see it: a damaged or unreadable record aborts reference
136		// collection before anything is deleted.
137		err = s.walkSnapshotRecords(func(_ string, snap Snapshot) error {
138			for _, entry := range snap.Entries {
139				referenced[entry.Digest] = struct{}{}
140			}
141			return nil
142		})
143		if err != nil {
144			return nil, err
145		}
146		return referenced, nil
147	}
148	
149	// loadStrict reads the current index for GC and verify. Unlike load it
150	// requires the document to be one complete JSON object with an explicitly
151	// present entries mapping: a bare null, an array, a primitive, truncated
152	// input, or trailing content after the object is corruption, and a missing
153	// or null entries mapping cannot be distinguished from "references lost".
154	// (A true {"entries":{}} remains a legitimate empty repository.) It also
155	// rejects any duplicate JSON key anywhere in the document — a repeated
156	// entries mapping, a repeated artifact name, or a repeated field inside one
157	// record — because encoding/json would silently keep only the last record
158	// and neither GC nor verify can tell which references the overwritten
159	// records carried. Keys are compared after JSON string decoding, so a name
160	// written directly and the same name written with Unicode escapes still
161	// collide.
162	//
163	// The entries field must also be spelled exactly "entries": encoding/json
164	// binds struct fields case-insensitively, so an "Entries" or "ENTRIES" field
165	// would silently populate the mapping — and, when both spellings appear,
166	// whichever comes last would silently overwrite the other. Any such variant
167	// is corruption whether it appears alone or beside the standard field, in
168	// either order, with identical or different content, empty or not. Field
169	// names are compared after JSON string decoding, so "entries" written
170	// through Unicode escapes is the standard field and stays valid while an
171	// escape that decodes to "Entries" is rejected. Unrelated extra top-level
172	// fields remain ignored.
173	func (s *Store) loadStrict() (index, error) {
