180			// distinctly from bytes that are present but malformed, so callers can
181			// name an unreadable index without calling it corrupt.
182			return index{}, fmt.Errorf("current index cannot be read: %w", err)
183		}
184		if err := rejectDuplicateKeys(data); err != nil {
185			return index{}, fmt.Errorf("current index is corrupt: %w", err)
186		}
187		// The document must be a JSON object: a bare null, array, or primitive is
188		// a corrupt index, never an empty mapping.
189		if trimmed := bytes.TrimSpace(data); len(trimmed) == 0 || trimmed[0] != '{' {
190			return index{}, errors.New("current index is corrupt: expected a JSON object with an entries mapping")
191		}
192		// A field that spells the entries mapping with different casing
193		// ("Entries", "ENTRIES", ...) would be silently bound to it by
194		// encoding/json — and would silently overwrite or be overwritten by the
195		// standard spelling when both appear — so any such field is corruption,
196		// regardless of order, content, or emptiness.
197		if err := rejectEntriesCaseVariants(data); err != nil {
198			return index{}, fmt.Errorf("current index is corrupt: %w", err)
199		}
200		var idx index
201		// json.Unmarshal rejects truncated input and trailing content after the
202		// top-level value.
203		if err := json.Unmarshal(data, &idx); err != nil {
204			return index{}, fmt.Errorf("current index is corrupt: %w", err)
205		}
206		if idx.Entries == nil {
207			return index{}, errors.New("current index is corrupt: missing entries mapping")
208		}
209		return idx, nil
210	}
211	
212	// rejectEntriesCaseVariants inspects the top-level field names of the index
213	// document and refuses any field whose decoded name matches "entries" only
214	// case-insensitively. encoding/json binds struct fields case-insensitively,
215	// so without this check an "Entries" field would silently populate the
216	// mapping on its own, and a document carrying both spellings would keep
217	// only whichever came last — dropping artifact records or replacing them
218	// with an empty mapping. Names are compared after JSON string decoding:
219	// "entries" written through Unicode escapes is the standard field and stays
220	// valid, while an escape decoding to a case variant is rejected. Duplicate
221	// exact keys were already rejected by rejectDuplicateKeys, so decoding the
222	// top level into a map cannot collapse two spellings of the same field.
223	// Fields unrelated to entries are ignored, as before.
224	func rejectEntriesCaseVariants(data []byte) error {
225		var top map[string]json.RawMessage
226		if err := json.Unmarshal(data, &top); err != nil {
227			return err
228		}
229		keys := make([]string, 0, len(top))
230		for key := range top {
231			keys = append(keys, key)
232		}
233		// Sorted so the reported field is deterministic when several vary.
234		sort.Strings(keys)
235		for _, key := range keys {
236			if key != "entries" && strings.EqualFold(key, "entries") {
237				return fmt.Errorf("field %q: the entries mapping must be spelled exactly \"entries\"", key)
238			}
239		}
240		return nil
241	}
242	
243	// loadStrictValidEntries loads the current mapping under loadStrict and then
244	// validates every record before returning it: the document must be one
245	// complete JSON object with an explicitly present entries mapping spelled
246	// exactly "entries" (a true {"entries":{}} is a legitimate empty repository;
247	// any case-variant spelling such as "Entries" is corruption, alone or beside
248	// the standard field), hold no duplicate key at any level (including a name
249	// written directly and again through Unicode escapes), and every record must
250	// pass validateEntryRecord. Records are
251	// checked in sorted name order so the first bad record reported is
252	// deterministic. One bad record fails the whole load; the caller never gets a
253	// partial mapping. This is the single gate list, put, get, verify, gc, and
254	// snapshot creation read the current mapping through.
255	func (s *Store) loadStrictValidEntries() (index, error) {
256		idx, err := s.loadStrict()
257		if err != nil {
258			return index{}, err
259		}
260		keys := make([]string, 0, len(idx.Entries))
261		for key := range idx.Entries {
262			keys = append(keys, key)
263		}
264		sort.Strings(keys)
265		for _, key := range keys {
266			if err := validateEntryRecord(key, idx.Entries[key]); err != nil {
267				return index{}, fmt.Errorf("current index is corrupt: %w", err)
268			}
269		}
270		return idx, nil
271	}
272	
273	// validateEntryRecord checks one index or snapshot entry the same way
274	// restore validates snapshot entries: the map key must equal the recorded
275	// name, the name must be legal, the digest must be 64 lowercase hex
276	// characters, and the size must not be negative.
277	func validateEntryRecord(key string, entry Entry) error {
278		if entry.Name != key {
279			return fmt.Errorf("entry %q is filed under %q", entry.Name, key)
280		}
281		if err := validateName(entry.Name); err != nil {
282			return fmt.Errorf("invalid entry name %q", entry.Name)
283		}
284		if !isDigest(entry.Digest) {
285			return fmt.Errorf("entry %q has digest %q, want 64 lowercase hex characters", entry.Name, entry.Digest)
286		}
287		if entry.Size < 0 {
288			return fmt.Errorf("entry %q has negative size %d", entry.Name, entry.Size)
289		}
290		return nil
291	}
