package vault

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeSnapshotRecord(t *testing.T, root, name, body string) {
	t.Helper()
	path := filepath.Join(root, "snapshots", filepath.FromSlash(name)+".json")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestCaseVariantEntriesRejected(t *testing.T) {
	variants := []string{
		`{"name":"releases/s1","Entries":{}}`,
		`{"name":"releases/s1","ENTRIES":{}}`,
		`{"name":"releases/s1","entries":{"a":{"name":"a","digest":"` + strings.Repeat("0", 64) + `","size":0,"createdAt":"2026-01-01T00:00:00Z"}},"Entries":{}}`,
		`{"name":"releases/s1","Entries":{},"entries":{}}`,
		`{"name":"releases/s1","Entries":{}}`,
	}
	for _, body := range variants {
		root := t.TempDir()
		s := New(root)
		if err := s.Init(); err != nil {
			t.Fatal(err)
		}
		writeSnapshotRecord(t, root, "releases/s1", body)
		if err := s.RestoreSnapshot("releases/s1"); err == nil || !strings.Contains(err.Error(), `snapshot "releases/s1" is corrupted`) || !strings.Contains(err.Error(), "entries") {
			t.Errorf("restore: body %s: got %v", body, err)
		}
		if _, err := s.ListSnapshots(); err == nil || !strings.Contains(err.Error(), "releases/s1") {
			t.Errorf("list: body %s: got %v", body, err)
		}
		if _, err := s.GC(true); err == nil {
			t.Errorf("gc dry-run: body %s: expected error", body)
		}
		if _, err := s.GC(false); err == nil {
			t.Errorf("gc: body %s: expected error", body)
		}
	}
}

func TestExactEntriesStillAccepted(t *testing.T) {
	// Unicode escape decoding to "entries" is the standard field.
	root := t.TempDir()
	s := New(root)
	if err := s.Init(); err != nil {
		t.Fatal(err)
	}
	writeSnapshotRecord(t, root, "s1", `{"name":"s1","entries":{}}`)
	if err := s.RestoreSnapshot("s1"); err != nil {
		t.Fatalf("restore escaped entries: %v", err)
	}
	infos, err := s.ListSnapshots()
	if err != nil || len(infos) != 1 || infos[0].Name != "s1" || infos[0].Count != 0 {
		t.Fatalf("list: %v %v", infos, err)
	}
}

func TestArtifactNamedEntriesPreserved(t *testing.T) {
	root := t.TempDir()
	s := New(root)
	if err := s.Init(); err != nil {
		t.Fatal(err)
	}
	src := filepath.Join(root, "in.bin")
	if err := os.WriteFile(src, []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}
	for _, n := range []string{"Entries", "App.bin", "app.bin"} {
		if _, err := s.Put(n, src); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := s.CreateSnapshot("snap"); err != nil {
		t.Fatal(err)
	}
	// Corrupt the current index; restore from the healthy snapshot must fix it.
	if err := os.WriteFile(filepath.Join(root, "index.json"), []byte("null"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := s.RestoreSnapshot("snap"); err != nil {
		t.Fatal(err)
	}
	entries, err := s.List()
	if err != nil || len(entries) != 3 {
		t.Fatalf("list after restore: %v %v", entries, err)
	}
}

